# POST /api/sheets/{sheetId}/claims/{claimId}/remind — remind an OPEN or PENDING claim: the sheet's today becomes its
# reminded date and REMIND is audited. A claim in any other status, or one already reminded on the sheet's today, is a
# 409 and a claim not on the sheet a 404, neither writing anything (a viewer is refused before, see ViewerGuard).
# Responds with the claim as stored.
validate:
  class: net.officefloor.hq.app.claim.ValidateRemind
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveReminder
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.RecordClaimReminded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Stores a reminder on the sheet's today, but only while the claim is OPEN or PENDING and not yet reminded that day. */
public class SaveReminder {
    public void save(@Val Claim claim, ClaimRepository claims, SheetRepository sheets)
            throws InvalidClaimStatusException {
        if (claim.status() != ClaimStatus.OPEN && claim.status() != ClaimStatus.PENDING) {
            throw new InvalidClaimStatusException("Only an OPEN or PENDING claim can be reminded");
        }
        if (!claims.remind(claim, sheets.today(claim.sheetId()))) {
            throw new InvalidClaimStatusException("The claim was already reminded today");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: who reminds the claim (a blank name is refused). */
public class ValidateRemind {
    public void validate(@RequestBody RemindRequest request, Out<ClaimReminder> reminder)
            throws InvalidClaimStatusException {
        String by = request == null || request.by() == null ? "" : request.by().trim();
        if (by.isEmpty()) {
            throw new InvalidClaimStatusException("Who reminds the claim is required");
        }
        reminder.set(new ClaimReminder(by));
    }
}
package net.officefloor.hq.app.claim;

/** A reminder once its body is read: who reminds the claim. */
public record ClaimReminder(String by) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;

/** Writes REMIND to the audit file once the reminder is stored, naming the claim (number=<number> when it has one). */
public class RecordClaimReminded {
    public void record(@Val Claim claim, @Val ClaimReminder reminder, PersonRepository people, Audit audit) {
        Person person = people.find(claim.sheetId(), claim.personId());
        audit.record("REMIND sheet=" + claim.sheetId() + " by=" + reminder.by() + " person="
                + (person == null ? "" : person.name()) + " amount=" + claim.amount().toPlainString()
                + " date=" + claim.date() + (claim.number() == null ? "" : " number=" + claim.number()));
    }
}
